  ('zcrm_5797994000003293021', 'Saaf Finance', 'Saaf Finance', 'Alexander Hilton', 'Ritvik Singh', 'Saaf Finance is a technology company that specializes in AI-powered automation solutions for the mortgage lending industry. Its main product is an advanced AI underwriting platform that automates and streamlines mortgage loan processing.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Have not Reached out', 'Alex Hilton', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-13 14:29:21', '2026-01-05 14:50:19', '2026-01-05 14:50:19'),
  ('zcrm_5797994000003293072', 'Finresi', 'Finresi', 'Alexander Hilton', 'Jeff Gophseti', 'Finresi is a digital platform that allows investors to participate in high yield real estate loans. Finresi partners with and purchases loans from a network of lenders whose loans end up on the Finresi marketplace.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Have not Reached out', 'Alex Hilton', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-13 14:50:03', '2026-01-05 14:50:19', '2026-01-05 14:50:19'),
  ('zcrm_5797994000003293109', 'Soil Action', 'Soil Action', 'Angela Zhang', 'Jack Oslan', 'Soil Action offers AI-enabled real-time soil analysis developed by the Foundational Model for Soil, which allows them to see into the ground, direct agricultural implements, unlock latent crop yield potential, improve plant and food nutrition, and reduce fertilizer waste and its environmental effects. This technology is aimed at enhancing soilmanagement and agricultural productivity.', 'HV Genesis', 'Sustainability', 'Fall 2025', NULL, 'Reached Out', 'Angela Zhang', 'Rejected', 'Sustainability', 'Founder Not Interested', NULL, '2025-10-13 21:22:19', '2025-10-28 12:49:02', '2025-10-28 12:49:02'),
  ('zcrm_5797994000003293144', 'Drink Barcode', 'Drink Barcode', 'Angela Zhang', 'Mubarak Malik', 'Drink Barcode is a plant-based and adaptogen-powered beverage that works with the body to keep the entire self at full potential. The company was founded in 2021 and is headquartered in Burlington, Vermont.', 'HV Genesis', 'Sustainability', 'Fall 2025', NULL, 'Have not Reached out', 'Angela Zhang', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', NULL, '2025-10-13 21:24:59', '2025-12-03 13:26:36', '2025-12-03 13:26:36'),
  ('zcrm_5797994000003293180', 'Alga Biosciences', 'Alga Biosciences', 'Angela Zhang', 'Alex brown', 'Alga Biosciences is a feed additive intended to eliminate agricultural methane emissions by cattle using algae. They use biochemistry to eliminate enteric methane emissions and provide natural red seaweed and feed additives, enabling farmers to save money and the community to fight against climate change and slow global warming.', 'HV Genesis', 'Sustainability', 'Fall 2025', NULL, 'Reached Out', 'Angela Zhang', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', NULL, '2025-10-13 21:27:52', '2025-12-03 13:27:23', '2025-12-03 13:27:23'),
