  ('zcrm_5797994000003293250', 'Bask Suncare', 'Bask Suncare', 'Angela Zhang', 'Michael Huffstetler', 'Bask Suncare offers sunscreen products online.', 'HV Genesis', 'Sustainability', 'Fall 2025', NULL, 'Reached Out', 'Angela Zhang', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', NULL, '2025-10-13 21:35:20', '2025-12-03 13:27:32', '2025-12-03 13:27:32'),
  ('zcrm_5797994000003293285', 'Dalan Animal Health', 'Dalan Animal Health', 'Angela Zhang', 'Annette Kleiser', 'Dalan Animal Health is a vaccine platform with the potential to combat a variety of devastating bee diseases. The company was founded in 2018 and is headquartered in Athens, Georgia, United States.', 'HV Genesis', 'Sustainability', 'Fall 2025', NULL, 'Reached Out', 'Angela Zhang', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', NULL, '2025-10-13 21:37:09', '2025-12-03 13:26:25', '2025-12-03 13:26:25'),
  ('zcrm_5797994000003293320', 'Bettani', 'Bettani', 'Angela Zhang', 'Oliver Zahn', 'Bettani is a data science company innovating the future of food. The company provides plant-based food technology to accelerate food innovation processes through focused experimentation, resulting in the rapid development of dairy alternatives optimized for taste, texture, nutrition, and cost, allowing clients to produce plant-based foods thatoutperform their animal-based predecessors.', 'HV Genesis', 'Sustainability', 'Fall 2025', NULL, 'Have not Reached out', 'Angela Zhang', 'Rejected', 'Sustainability', NULL, NULL, '2025-10-13 21:39:44', '2026-01-05 14:50:19', '2026-01-05 14:50:19'),
  ('zcrm_5797994000003293474', 'Smartlens', 'Smartlens', 'Priyanshi Sitlani', 'Savas Komban', 'Developer of a wearable device intended to prevent the progression of glaucoma and irreversible blindness. The company''s technology utilizes a microfluidic-based smart contact lens and a smartphone app powered to monitor intraocular pressure, clinical trials have demonstrated a strong correlation with office-based standard-of-care devices, positioning the company as the first to offer an accurate and convenient method for monitoring the risk and progression of glaucoma, enabling patients to get an efficient and convenient way of monitoring IOP at home.', 'HV STEM', 'SaaS', 'Fall 2025', NULL, 'Reached Out', 'Priyanshi Sitlani', 'Rejected', NULL, NULL, NULL, '2025-10-14 18:11:15', '2026-01-28 07:17:45', '2026-01-28 07:17:45'),
