  ('zcrm_5797994000003293552', 'advntblanket.tech', 'AdvntBlanket', 'Kortney St. Preux', 'Jose Soto', 'Provider of AI-powered technology services intended to address the unique challenges faced by small and medium businesses. The company offers services such as Ai-powered it, cybersecurity and compliance for law firms and in-house legal teams, modern it and automation for digital-first transformation and more.', 'HV STEM', 'SaaS', 'Fall 2025', 'PitchBooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, 'Founder Not Interested', NULL, '2025-10-15 06:39:56', '2026-02-26 15:51:19', '2026-02-26 15:51:19'),
  ('zcrm_5797994000003293578', 'rivanna.ai', 'rivanna', 'Kortney St. Preux', 'unknown unknown', 'Developer of artificial intelligence solutions for the finance sector designed to enhance data analysis and streamline reporting. The company offers a copilot tool that enables users to run analyses, extract data from sources, and generate outputs compatible with Excel, utilizing natural language processing. Their technology aims to improve efficiency and accuracy in financial operations.', 'HV STEM', 'SaaS', 'Fall 2025', 'Pitchbooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, 'Founder Fit;Founder Communication (no response etc.)', NULL, '2025-10-15 06:47:00', '2026-02-26 15:51:04', '2026-02-26 15:51:04'),
  ('zcrm_5797994000003293604', 'DocuLynx', 'DocuLynx', 'Kortney St. Preux', 'Natalie Schubert', 'Developer of business process software intended to serve construction and engineering, insurance, energy, education, government, and healthcare sectors. The company''s software offers document imaging services, human resource automation, document scanning, data management, document conversion, and image migration services, thereby helping companies manage their information to optimize their business processes.', 'HV STEM', 'SaaS', 'Fall 2025', 'PitchBooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, NULL, NULL, '2025-10-15 06:52:05', '2026-02-26 15:50:46', '2026-02-26 15:50:46'),
  ('zcrm_5797994000003293631', 'Averroes', 'averroes', 'Kortney St. Preux', 'Tareq Aljaber', 'Developer of an artificial intelligence application designed for the automated creation of custom AI models for industrial companies. The company provides visual inspection, predictive maintenance, quality testing, and yield prediction for AI models, enabling manufacturing companies to save time by addressing defects automatically instead of searching for them.', 'HV STEM', 'SaaS', 'Fall 2025', 'PitchBooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, 'Founder Not Interested', NULL, '2025-10-15 06:56:21', '2026-02-26 15:45:32', '2026-02-26 15:45:32'),
