  ('zcrm_5797994000003293683', 'Sensigo', 'Sensigo', 'Kortney St. Preux', 'Rakesh Hegde', 'Sensigo, founded in 2023 and based in San Carlos, develops a vehicle service platform that assists technicians in diagnosing issues, predicting failures, and streamlining parts procurement. The company has 15 employees.', 'HV STEM', 'SaaS', 'Fall 2025', 'Pitchbooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, 'Founder Not Interested', NULL, '2025-10-15 07:11:17', '2026-02-26 15:45:18', '2026-02-26 15:45:18'),
  ('zcrm_5797994000003293709', 'prezerv.ai', 'prezerv.ai', 'Kortney St. Preux', 'Cam Raufi', 'Developer of three-dimensional mapping platform designed to improve the lifecycle management of civil infrastructure. The company''s platform leverages AI and advanced non-destructive technologies to create highly accurate digital twins, enabling clients to optimize planning, construction, and maintenance processes, ultimately reducing costs, minimizing risks, and accelerating project timelines.', 'HV STEM', 'SaaS', 'Fall 2025', 'PitchBooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, 'Founder Not Interested', NULL, '2025-10-15 07:14:17', '2026-02-26 15:44:22', '2026-02-26 15:44:22'),
  ('zcrm_5797994000003293735', 'Vizonare', 'vizonare', 'Kortney St. Preux', 'Przemek Blasiak', 'Developer of a spatial computing platform designed to plan, visualize, and guide works using 3D models of physical locations. The company''s platform offers a software solution for remote site visits and collaboration on projects in physical spaces, based on mobile 3D scans and mixed reality, enabling users to cut site visit costs, travel time, and the related carbon footprint.', 'HV STEM', 'SaaS', 'Fall 2025', 'PitchBooks', 'Reached Out', 'Kortney St Preux', 'Rejected', NULL, 'Founder Not Interested', NULL, '2025-10-15 07:16:28', '2026-02-26 15:44:44', '2026-02-26 15:44:44'),
  ('zcrm_5797994000003293770', 'DownToBid', 'DownToBid', 'Jacob Dooley', 'Kevin Wu', 'Downtobid provides an AI-driven platform that automates the construction bidding process by analyzing construction drawings to create bid packages and tailored lists of subcontractor invitations. The technology features automated drawing analysis, invitation drafting, and real-time access to contractor data, aimed at enhancing bidding efficiency.', 'HV Genesis', 'Financial Innovation', 'Fall 2025', NULL, 'Reached Out', 'Jacob Dooley', 'Rejected', 'Financial Innovation', NULL, NULL, '2025-10-16 06:23:15', '2026-01-05 14:50:19', '2026-01-05 14:50:19'),
