  ('zcrm_5797994000003294692', 'Envision Health', 'Envision Health', 'Brandon McClean', 'Lama Al Aswad', 'Developer of assistive technology devices designed to support individuals with visual impairments in daily activities. The company offers wearable devices that use computer vision and audio feedback for navigation, object and text recognition, and situational awareness, enabling people with vision loss to navigate environments safely and supporting accessibility for users and organizations.', 'HV STEM', 'Healthcare', 'Fall 2025', NULL, 'Reached Out', 'Brandon McClean', 'On Hold', NULL, NULL, NULL, '2025-10-14 17:32:38', '2026-02-12 12:03:40', '2026-02-12 12:03:40'),
  ('zcrm_5797994000003294735', 'Clinware', 'Clinware', 'Brandon McClean', 'Clinware Info', 'Developer of healthcare automation software designed for streamlining clinical and financial workflows. The company''s platform automates patient referrals, documentation, and reimbursement processes using AI-driven analytics, machine learning algorithms, and secure EHR integrations, enabling healthcare providers to reduce administrative burden, improve compliance, optimize revenue cycles, and make data-informed decisions.', 'HV STEM', 'Healthcare', 'Fall 2025', NULL, 'Reached Out', 'Brandon McClean', 'On Hold', NULL, NULL, NULL, '2025-10-14 17:42:02', '2026-02-12 12:03:20', '2026-02-12 12:03:20'),
  ('zcrm_5797994000003294766', 'Nerveli', 'Nerveli', 'Brandon McClean', 'Leon Jacobson', 'Developer of a pain management app designed to understand and manage chronic aching through personalized and evidence-based approaches. The company offers symptom tracking, behavioral therapy, educational content, and data-driven insights through a mobile application, enabling health insurers, employers, and healthcare providers to assist individuals and employees in gaining better control over their pain, reducing stress, and improving overall well-being.', 'HV STEM', 'Healthcare', 'Fall 2025', 'Pitchbook', 'Reached Out', 'Brandon McClean', 'On Hold', NULL, NULL, NULL, '2025-10-14 17:43:54', '2026-02-12 12:01:02', '2026-02-12 12:01:02'),
  ('zcrm_5797994000003294797', 'Rheumasense', 'Rheumasense', 'Brandon McClean', 'Jennifer Skeen', 'Developer of a diagnostics technology designed to reshape chronic disease management and rheumatoid arthritis care. The company combines Liquid Chromatography-Mass Spectrometry (LC-MS) biomarker testing with machine learning analytics to deliver real-time, objective insights into rheumatoid arthritis (RA) disease activity, enabling clients to measure a specific, accurate, and quantitative view of disease levels.', 'HV STEM', 'Healthcare', 'Fall 2025', NULL, 'Reached Out', 'Brandon McClean', 'On Hold', NULL, NULL, NULL, '2025-10-14 17:46:16', '2026-02-12 12:00:40', '2026-02-12 12:00:40'),
